class Solution:
    def canMerge(self, trees: List[TreeNode]) -> Optional[TreeNode]:
        child_vals = set()
        for t in trees:
            if t.left:
                child_vals.add(t.left.val)
            if t.right:
                child_vals.add(t.right.val)
        roots = [t for t in trees if t.val not in child_vals]
        if len(roots) != 1:
            return None
        root = roots[0]
        rest = [t for t in trees if t is not root]

        progress = True
        while progress and rest:
            progress = False
            for i, cand in enumerate(rest):
                leaf = self._find_leaf(root, cand.val)
                if leaf:
                    leaf.left, leaf.right = cand.left, cand.right
                    rest.pop(i)
                    progress = True
                    break
        if rest:
            return None
        return root if self._inorder_valid(root) else None

    def _find_leaf(self, node, target):
        stack = [node]
        while stack:
            cur = stack.pop()
            if not cur.left and not cur.right:
                if cur.val == target:
                    return cur
            else:
                if cur.left:
                    stack.append(cur.left)
                if cur.right:
                    stack.append(cur.right)
        return None

    def _inorder_valid(self, root):
        prev = float("-inf")
        stack, node = [], root
        while stack or node:
            while node:
                stack.append(node)
                node = node.left
            node = stack.pop()
            if node.val <= prev:
                return False
            prev = node.val
            node = node.right
        return True

