class Solution {
    public TreeNode canMerge(List<TreeNode> trees) {
        Set<Integer> childVals = new HashSet<>();
        for (TreeNode t : trees) {
            if (t.left != null) childVals.add(t.left.val);
            if (t.right != null) childVals.add(t.right.val);
        }
        TreeNode root = null;
        int rootCount = 0;
        for (TreeNode t : trees)
            if (!childVals.contains(t.val)) { rootCount++; root = t; }
        if (rootCount != 1) return null;
        List<TreeNode> rest = new ArrayList<>();
        for (TreeNode t : trees) if (t != root) rest.add(t);

        boolean progress = true;
        while (progress && !rest.isEmpty()) {
            progress = false;
            for (Iterator<TreeNode> it = rest.iterator(); it.hasNext();) {
                TreeNode cand = it.next();
                TreeNode leaf = findLeaf(root, cand.val);
                if (leaf != null) {
                    leaf.left = cand.left;
                    leaf.right = cand.right;
                    it.remove();
                    progress = true;
                    break;
                }
            }
        }
        if (!rest.isEmpty()) return null;
        return inorderValid(root) ? root : null;
    }

    private TreeNode findLeaf(TreeNode node, int target) {
        Deque<TreeNode> st = new ArrayDeque<>();
        st.push(node);
        while (!st.isEmpty()) {
            TreeNode cur = st.pop();
            if (cur.left == null && cur.right == null) {
                if (cur.val == target) return cur;
            } else {
                if (cur.left != null) st.push(cur.left);
                if (cur.right != null) st.push(cur.right);
            }
        }
        return null;
    }

    private boolean inorderValid(TreeNode root) {
        long prev = Long.MIN_VALUE;
        Deque<TreeNode> st = new ArrayDeque<>();
        TreeNode node = root;
        while (!st.isEmpty() || node != null) {
            while (node != null) { st.push(node); node = node.left; }
            node = st.pop();
            if (node.val <= prev) return false;
            prev = node.val;
            node = node.right;
        }
        return true;
    }
};

