                auto it = openTrees.find(child->val);
                if (it != openTrees.end()) {
                    TreeNode* sub = it->second;
                    openTrees.erase(it);
                    child->left = sub->left;
                    child->right = sub->right;
                }
                st.push_back(child);
            }
