        const node = stack.pop();
        for (const child of [node.left, node.right]) {
            if (!child) continue;
            if (openTrees.has(child.val)) {
                const sub = openTrees.get(child.val);
                openTrees.delete(child.val);
                child.left = sub.left;
                child.right = sub.right;
